@page "/apply"
@namespace sv_90b63ed6e3634e71a451b47d97065be1.Components.Pages.Apply
@using sv_90b63ed6e3634e71a451b47d97065be1.Services
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="_currentStep" OnStepSelected="GoToStep" />

    <div class="step-content">
        @switch (_currentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@_fullName" FullNameChanged="v => _fullName = v"
                                  Email="@_email" EmailChanged="v => _email = v"
                                  Phone="@_phone" PhoneChanged="v => _phone = v"
                                  Address="@_address" AddressChanged="v => _address = v"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync"
                                  OnNext="NextStep" />
                break;
            case 1:
                <WorkHistoryStep Entries="_workEntries" EntriesChanged="v => _workEntries = v"
                                 OnNext="NextStep" OnBack="PreviousStep" />
                break;
            case 2:
                <ReferencesStep References="_references" ReferencesChanged="v => _references = v"
                                OnNext="NextStep" OnBack="PreviousStep" />
                break;
            case 3:
                <CoverLetterStep CoverLetter="@_coverLetter" CoverLetterChanged="v => _coverLetter = v"
                                 OnNext="NextStep" OnBack="PreviousStep" />
                break;
            case 4:
                <ReviewStep FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                            WorkEntries="_workEntries" References="_references"
                            CoverLetter="@_coverLetter"
                            OnEditSection="GoToStep" OnBack="PreviousStep"
                            OnSubmit="SubmitApplication" />
                break;
        }
    </div>
</div>

@code {
    private int _currentStep;
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";
    private List<WorkEntryForm.WorkEntryModel> _workEntries = new() { new() };
    private List<ReferenceForm.ReferenceModel> _references = new() { new(), new() };
    private string _coverLetter = "";

    private void NextStep() => _currentStep++;
    private void PreviousStep() => _currentStep--;
    private void GoToStep(int step) => _currentStep = step;

    private async Task<int> SubmitApplication()
    {
        var application = new Models.JobApplication(
            new Models.PersonalInfo(_fullName, _email, _phone, _address),
            new Models.WorkHistory(_workEntries.Select(e =>
                new Models.WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()),
            _references.Select(r =>
                new Models.Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            _coverLetter
        );

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

