@namespace sv_90b63ed6e3634e71a451b47d97065be1.Components.Pages.Apply

<div class="work-entry-form">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button class="btn btn-danger-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company" @onchange="OnCompanyChanged" class="form-control" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title" @onchange="OnTitleChanged" class="form-control" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="OnStartDateChanged" class="form-control" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@(Entry.EndDate?.ToString("yyyy-MM-dd"))" @onchange="OnEndDateChanged" class="form-control" disabled="@_isCurrent" />
        </div>

        <div class="form-group checkbox-group">
            <label>
                <input type="checkbox" checked="@_isCurrent" @onchange="ToggleCurrent" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Entry.Description" @onchange="OnDescriptionChanged" class="form-control" rows="3"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool _isCurrent;

    protected override void OnParametersSet()
    {
        _isCurrent = Entry.EndDate is null && Entry.StartDate != default;
    }

    private void OnCompanyChanged(ChangeEventArgs e)
    {
        Entry.Company = e.Value?.ToString() ?? "";
        OnEntryChanged.InvokeAsync(Entry);
    }

    private void OnTitleChanged(ChangeEventArgs e)
    {
        Entry.Title = e.Value?.ToString() ?? "";
        OnEntryChanged.InvokeAsync(Entry);
    }

    private void OnStartDateChanged(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
            Entry.StartDate = date;
        OnEntryChanged.InvokeAsync(Entry);
    }

    private void OnEndDateChanged(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        Entry.EndDate = string.IsNullOrEmpty(val) ? null : DateTime.TryParse(val, out var d) ? d : null;
        OnEntryChanged.InvokeAsync(Entry);
    }

    private void OnDescriptionChanged(ChangeEventArgs e)
    {
        Entry.Description = e.Value?.ToString() ?? "";
        OnEntryChanged.InvokeAsync(Entry);
    }

    private void ToggleCurrent(ChangeEventArgs e)
    {
        _isCurrent = (bool)(e.Value ?? false);
        if (_isCurrent)
        {
            Entry.EndDate = null;
            OnEntryChanged.InvokeAsync(Entry);
        }
    }

